INSERT INTO case_studies
    (project_id, overview, context, problem, role, approach, architecture,
     database_notes, api_notes, security, deployment, outcome,
     features, challenges, decisions, updated_at)
VALUES
    (@pid, 'A portfolio built as a production system rather than a static page, so the engineering choices on display are the ones actually running the site.', NULL, 'A portfolio has almost no inherent backend requirement. The interesting constraint is deciding where complexity is justified: adding a database and an API service for their own sake would contradict the judgement the site is meant to demonstrate.', 'Sole developer — design system, frontend, API, schema, containers, deployment documentation.',
     'Content lives in typed TypeScript modules and is prerendered, so pages ship as static HTML with no runtime data dependency. Only the contact form needs server behaviour, so that is the only thing with an API and a table behind it.', 'Cloudflare terminates TLS and fronts the origin. Nginx reverse-proxies to the Nuxt server, which prerenders every content route. The browser posts the contact form to a Nuxt server route, which forwards it server-side to the Go API — the API is never reachable from the public internet, so it needs no CORS surface. The Go service validates, rate-limits, and persists to MySQL.', 'One table, contact_messages, holding the submission plus request metadata for abuse investigation. Migrations are plain, numbered, forward-and-back SQL files — no ORM, because there is no schema complexity to justify one.', 'Go net/http with a small middleware chain: request ID, structured logging, panic recovery, body-size limit, security headers, and a per-IP token-bucket limiter. Two routes: POST /v1/contact and GET /health.',
     'The API binds to the container network only. Input is validated and length-bounded server-side before it reaches the database, statements are parameterised, error responses never echo internals, and secrets come from the environment rather than the image.', 'docker compose builds both services against a MySQL container with a persistent volume and health-gated startup ordering. The same compose file plus an env file is what runs in production behind Nginx.', 'The site is fully prerendered, keyboard accessible, and works with JavaScript-driven animation disabled. Build, typecheck, lint, and the API test suite all run clean.',
     '["Prerendered content routes with typed content modules","Dark, light, and system theme with persisted preference","Per-project case-study pages that render only verified sections","Contact API with validation, per-IP rate limiting, and honeypot spam protection","Person, WebSite, and CreativeWork structured data","Generated sitemap and robots.txt","Multi-stage Docker builds for both services with health checks"]', NULL, '[{"decision":"Prerender content routes instead of serving them from the database","rationale":"The content changes when I change it, not per request. Prerendering removes the database from the critical path for every page a visitor actually reads, so the site stays up and fast even if the API is down."},{"decision":"Proxy the contact form through the Nuxt server rather than calling Go from the browser","rationale":"It keeps the Go service unreachable from the internet and removes the need for a public CORS policy. The cost is one extra internal hop on a route that runs a few times a day."},{"decision":"No CMS or admin panel","rationale":"One author editing typed files gets type safety and version history for free. An admin panel would add authentication, sessions, and an attack surface to solve a problem that does not exist yet."}]', @now)
ON DUPLICATE KEY UPDATE project_id = project_id;

