INSERT INTO site_settings (setting_key, setting_value, updated_at) VALUES ('about_paragraphs', '["I am a full-stack software developer with professional development experience since 2020. I work across backend systems, frontend applications, mobile development, databases, APIs, infrastructure, deployment, and production operations.","Most of my work has been building and running complete systems rather than isolated features: designing the data model, writing the API, building the interface that consumes it, then deploying and maintaining the result. That shapes how I make decisions — I favour structures that stay readable a year later, and I plan for the failure modes before they reach production."]', @now) ON DUPLICATE KEY UPDATE setting_key = setting_key;
